let ShellNames = dynamic(["cmd.exe", "powershell.exe", "pwsh.exe", "powershell_ise", "wscript.exe", "cscript.exe", "mshta.exe",
"rundll32.exe", "regsvr32.exe", "certutil.exe", "bitsadmin.exe", "curl.exe", "wmic.exe", "schtasks.exe", "msbuild.exe",
"installutil.ex", "regasm.exe", "regsvcs.exe", "msiexec.exe", "hh.exe", "forfiles.exe", "msdt.exe", "odbcconf.exe",
"net.exe", "net1.exe", "whoami.exe", "nltest.exe", "reg.exe", "sc.exe", "bash.exe", "wsl.exe", "certreq.exe",
"bcdedit.exe", "vssadmin.exe", "wevtutil.exe", "netsh.exe", "systeminfo.exe", "quser.exe", "qwinsta.exe",
"hostname.exe", "ipconfig.exe", "arp.exe", "nslookup.exe", "tasklist.exe", "taskkill.exe", "cmstp.exe",
"psexec.exe", "psexec64.exe", "adfind.exe"]);
let Det_ParentChild = () {
let office = dynamic(["winword.exe", "excel.exe", "powerpnt.exe", "msaccess.exe", "mspub.exe", "onenote.exe", "visio.exe",
"eqnedt32.exe", "outlook.exe", "wordpad.exe", "wordview.exe"]);
let webServers = dynamic(["w3wp.exe", "httpd.exe", "nginx.exe", "php.exe", "php-cgi.exe", "tomcat.exe", "tomcat8.exe",
"tomcat9.exe", "java.exe", "javaw.exe", "sqlservr.exe", "umworkerproces", "caddy.exe"]);
let accessibility = dynamic(["winlogon.exe", "logonui.exe", "utilman.exe", "sethc.exe", "osk.exe", "magnify.exe",
"narrator.exe", "atbroker.exe", "displayswitch."]);
let lolParents = dynamic(["mshta.exe", "rundll32.exe", "regsvr32.exe", "bitsadmin.exe", "wscript.exe", "cscript.exe",
"msbuild.exe", "installutil.ex"]);
let quiet = dynamic(["taskhostw.exe", "runtimebroker.", "dwm.exe", "fontdrvhost.ex", "sihost.exe", "ctfmon.exe",
"searchindexer.", "searchprotocol", "conhost.exe"]);
let shells = dynamic(["cmd.exe", "powershell.exe", "pwsh.exe", "powershell_ise", "rundll32.exe", "mshta.exe", "regsvr32.exe",
"wscript.exe", "cscript.exe"]);
ProcTree()
| where ParentState == "found"
| extend LName = tolower(Name), LParent = tolower(ParentName)
| extend Rule = case(
LParent == "lsass.exe" and LName != "efsui.exe", "Critical|lsass.exe spawned a child process",
LParent in (accessibility) and LName in (shells), "Critical|Shell spawned by a logon/accessibility process (sticky-keys style backdoor)",
LParent in (office) and LName in (ShellNames), "High|Office application spawned a shell, script host or LOLBin",
LParent == "wmiprvse.exe" and LName in (ShellNames) and LName != "msiexec.exe", "High|WMI provider host spawned a shell (remote WMI execution)",
LParent in ("wsmprovhost.ex", "winrshost.exe") and LName in (ShellNames), "High|WinRM host spawned a shell (PowerShell remoting / winrs)",
LParent == "services.exe" and LName in ("cmd.exe", "powershell.exe", "pwsh.exe", "rundll32.exe", "msbuild.exe", "mshta.exe"), "High|services.exe spawned a shell (service-based execution, e.g. PsExec/getsystem)",
LParent == "spoolsv.exe" and LName in (ShellNames) and LName != "rundll32.exe", "High|Print spooler spawned a shell or tool",
LParent in (webServers) and LName in (ShellNames), "High|Web/application server spawned a shell (web shell)",
LParent in (lolParents) and LName in (shells), "High|LOLBin spawned a shell",
LParent in (quiet) and LName in (shells), "Medium|Quiet system process spawned a shell",
"")
| where isnotempty(Rule)
| parse Rule with Severity "|" Finding
| project PID, Process = Name, Severity, Category = "Execution", Finding,
Detail = strcat(ParentName, " (", PPID, ") -> ", Name, " (", PID, ")", iff(isnotempty(CommandLine), strcat(": ", CommandLine), ""))
};
let SevRank = (severity:string) {
case(severity == "Critical", 4, severity == "High", 3, severity == "Medium", 2, severity == "Low", 1, 0)
};
Det_ParentChild()
| extend SeverityRank = SevRank(Severity)
| order by SeverityRank desc
| project-away SeverityRank", "clusterName": "{Clustername}", "databaseName": "{Databases}"}

{"version": "AzureDataExplorerQuery/1.0", "queryText": "let Leaf = (path:string) { tostring(split(replace_string(path, "/", @"\"), @"\")[-1]) };
let NormPath = (path:string) {
let p = tolower(trim(@"[\s""]", path));
replace_regex(replace_regex(replace_regex(replace_regex(replace_regex(p,
@"^\\\\\?\\", ""),
@"^\\\?\?\\", ""),
@"^(\\systemroot|%systemroot%)\\", @"c:\\windows\\"),
@"^\\device\\harddiskvolume\d+\\", @"c:\\"),
@"^\\windows\\", @"c:\\windows\\")
};
let Procs = () {
let listed = pslist
| project ProcKey = strcat(PID, "|", CreateTime), PID, PPID, Name = ImageFileName, CreateTime, ExitTime,
Threads, Handles, SessionId, Wow64, InPslist = true;
let scanned = psscan
| project ProcKey = strcat(PID, "|", CreateTime), PID, PPID, Name = ImageFileName, CreateTime, ExitTime,
Threads, Handles, SessionId, Wow64, InPsscan = true;
let images = union
(pebmasquerade | where EPROCESS_SeAudit_ImageFileName !in ("", "-") | project PID, Path = EPROCESS_SeAudit_ImageFileName, Rank = 1),
(dlllist | where Path endswith ".exe" | summarize arg_min(VolRow, Path) by PID | project PID, Path, Rank = 2)
| summarize arg_min(Rank, Path) by PID
| project PID, ImagePath = NormPath(Path);
let commands = cmdline
| where Args !in ("", "-") and not(Args startswith "Required memory") and Args !contains "process exited"
| summarize CommandLine = take_any(Args) by PID;
let users = getsids | summarize arg_min(VolRow, SID, Name) by PID | project PID, UserSid = SID, UserLabel = Name;
listed
| join kind=fullouter scanned on ProcKey
| project ProcKey = coalesce(ProcKey, ProcKey1), PID = coalesce(PID, PID1), PPID = coalesce(PPID, PPID1),
Name = coalesce(Name, Name1), CreateTime = coalesce(CreateTime, CreateTime1), ExitTime = coalesce(ExitTime, ExitTime1),
Threads = coalesce(Threads, Threads1), Handles = coalesce(Handles, Handles1), SessionId = coalesce(SessionId, SessionId1),
Wow64 = coalesce(Wow64, Wow641), InPslist = coalesce(InPslist, false), InPsscan = coalesce(InPsscan, false)
| lookup kind=leftouter images on PID
| lookup kind=leftouter commands on PID
| lookup kind=leftouter users on PID
| extend ImagePath = iff(InPslist, ImagePath, ""), CommandLine = iff(InPslist, CommandLine, ""),
UserSid = iff(InPslist, UserSid, ""), UserLabel = iff(InPslist, UserLabel, "")
| extend ImageName = iff(isnotempty(ImagePath), Leaf(ImagePath), tolower(Name)), Exited = isnotnull(ExitTime)
};
let ProcTree = () {
let p = Procs();
let parents = p
| project PPID = PID, ParentKey = ProcKey, ParentName = Name, ParentImage = ImageName, ParentCreateTime = CreateTime,
ParentExitTime = ExitTime, ParentPath = ImagePath, ParentCommandLine = CommandLine,
ParentUserSid = UserSid, ParentSessionId = SessionId;
let matched = p
| join kind=inner parents on PPID
| where PPID == 4 or isnull(CreateTime) or isnull(ParentCreateTime) or ParentCreateTime <= CreateTime + 10s
| summarize arg_max(ParentCreateTime, *) by ProcKey
| project-away PPID1
| extend ParentState = "found";
let unmatched = p
| join kind=leftanti matched on ProcKey
| join kind=leftouter (parents | summarize Later = count() by PPID) on PPID
| extend ParentState = iff(coalesce(Later, 0) > 0, "pid-reused", "gone")
| project-away PPID1, Later;
union matched, unmatched
};
let Det_Identity = () {
let shells = dynamic(["cmd.exe", "powershell.exe", "pwsh.exe", "rundll32.exe", "mshta.exe", "wscript.exe", "cscript.exe", "regsvr32.exe"]);
let tree = ProcTree() | where not(Exited) | extend LName = tolower(Name);
let systemShell = tree
| where UserSid == "S-1-5-18" and SessionId >= 1 and LName in (shells)
| project PID, Process = Name, Severity = "High", Finding = "Shell running as SYSTEM in an interactive session",
Detail = strcat(Name, " in session ", SessionId, " started by ", coalesce(ParentName, "?"), ": ", CommandLine);
let potato = tree
| where UserSid == "S-1-5-18" and (ParentUserSid in ("S-1-5-19", "S-1-5-20") or ParentUserSid startswith "S-1-5-80-" or ParentUserSid startswith "S-1-5-82-")
| project PID, Process = Name, Severity = "High", Finding = "SYSTEM process started by a service account (SeImpersonate/potato privilege escalation?)",
Detail = strcat(ParentName, " (", ParentUserSid, ") -> ", Name, " (SYSTEM)");
let userAsSystem = tree
| where UserSid == "S-1-5-18" and LName in ("explorer.exe", "runtimebroker.", "sihost.exe", "ctfmon.exe")
| project PID, Process = Name, Severity = "High", Finding = "User-session process running as SYSTEM",
Detail = strcat(Name, " token user is SYSTEM (expected the logged-on user)");
union systemShell, potato, userAsSystem
| extend Category = "Execution"
};
Det_Identity()", "clusterName": "{Clustername}", "databaseName": "{Databases}"}

